namespace ghidra.pcode.emu.symz3;

using ghidra.debug.api.emulation;
using ghidra.debug.api.emulation;
using ghidra.pcode.emu;
using ghidra.pcode.emu.symz3.state;
using ghidra.pcode.emu.symz3.state;
using ghidra.pcode.exec.trace;
using ghidra.pcode.exec.trace.TraceEmulationIntegration;
using ghidra.pcode.exec.trace.data;

/**
 * An emulator factory for making the {@link SymZ3PcodeEmulator} discoverable to the UI
 * <p>
 * This is the final class to create a full Debugger-integrated emulator. This class is what makes
 * it appear in the menu of possible emulators the user may configure.
 */
public class SymZ3EmulatorFactory : EmulatorFactory {
	public static readonly string TITLE = "Symbolic Z3 Summary with Concrete Emulation";

	public static Writer delayedWriteTrace(PcodeTraceAccess access) {
		Writer writer = TraceEmulationIntegration.bytesDelayedWrite(access);
		addHandlers(writer);
		return writer;
	}

	public static void addHandlers(Writer writer) {
		writer.putHandler(new SymZ3PieceHandler());
	}

	/* @Override */
	public string getTitle() {
		return TITLE;
	}

	/* @Override */
	public PcodeMachine<object> create(PcodeDebuggerAccess access, Writer writer) {
		addHandlers(writer);
		return new SymZ3PcodeEmulator(access.getLanguage(), writer.callbacks());
	}
}
